# ESERCIZI DELLA SIMULAZIONE BRAND (30/10/2026), con strategia e ufficio stampa (decisione di Queen).
# Stessa struttura delle altre simulazioni. Risposte coerenti con genera_brand.py. Testi scritti da Claude: DA RILEGGERE.
# Le funzioni qui sotto sono le stesse di crea_esercizi_social.py.
import json
S = "/app/simulazioni/brand"
def opz(*xs): return [{"id": f"o{i+1}", "testo": t, "giusta": g, "nota": n} for i, (g, t, n) in enumerate(xs)]
def scelta(strumento, domanda, consegna, spiega, esempio, errore, opzioni, perche, aiuto, dove="", tipo="radio", pagina=None):
    p = {"strumento": strumento, "tipo": tipo, "domanda": domanda, "consegna": consegna, "spiega": spiega, "esempio": esempio, "errore": errore, "opzioni": opzioni, "perche": perche, "aiuto": aiuto, "dove": dove}
    if pagina: p["pagina"] = pagina
    return p
def azione(strumento, verifica, vai, domanda, consegna, spiega, esempio, errore, perche, aiuto, dove="", negozio=""):
    return {"strumento": strumento, "tipo": "azione", "verifica": verifica, "vai": vai, "negozio": negozio, "domanda": domanda, "consegna": consegna, "spiega": spiega, "esempio": esempio, "errore": errore, "opzioni": [], "perche": perche, "aiuto": aiuto, "dove": dove}
def testo(verifica, domanda, consegna, spiega, esempio, errore, perche, aiuto="", parole=(30, 160)):
    return {"strumento": "guida", "tipo": "testo", "verifica": verifica, "domanda": domanda, "consegna": consegna, "spiega": spiega, "esempio": esempio, "errore": errore, "opzioni": [], "perche": perche, "aiuto": aiuto, "dove": "", "parole": list(parole)}
def info(strumento, domanda, spiega, come, dove=""):
    return {"strumento": strumento, "tipo": "info", "domanda": domanda, "consegna": "", "spiega": spiega, "esempio": "", "errore": "", "come": come, "opzioni": [], "perche": "", "aiuto": "", "dove": dove}
def es(id, liv, n, nome, tempo, strumenti, cosa, situazione, obiettivo, passi, imparato, elena, prepara=None):
    e = {"id": id, "livello": liv, "n": n, "nome": nome, "tempo": tempo, "strumenti": strumenti, "cosa": cosa, "situazione": situazione, "obiettivo": obiettivo, "passi": passi, "imparato": imparato, "elena": elena}
    if prepara: e["prepara"] = prepara
    return e
def V(pag, testo): return {"link": f"{S}/{pag}/", "testo": testo}
MAN, IND, TES, PIA, STA = V("manuale", "Apri il Manuale"), V("ricerche", "Apri le Ricerche"), V("testi", "Apri i Testi"), V("piano", "Apri il Piano"), V("stampa", "Apri l'Ufficio stampa")

